import React from "react";
import { NavLink } from "react-router-dom";
import {
  Home,
  ShoppingCart,
  Users,
  Book,
  Truck,
  BookPlus,
  Printer,
  Import,
  ListChecks,
  Package,
  Pencil,
  LogOut,
} from "lucide-react";

interface SidebarItem {
  icon: React.ReactNode;
  label: string;
  path: string;
}

interface SidebarProps {
  onLogout?: () => void;
}

const Sidebar: React.FC<SidebarProps> = ({ onLogout }) => {
  const menuItems: SidebarItem[] = [
    { icon: <Home size={20} />, label: "Dashboard", path: "/dashboard" },
    { icon: <Users size={20} />, label: "Users Management", path: "/admin/users" },
    { icon: <Book size={20} />, label: "Books Management", path: "/admin/books" },
    { icon: <BookPlus size={20} />, label: "Add Books", path: "/admin/addbookpage" },
    { icon: <ShoppingCart size={20} />, label: "Orders Management", path: "/admin/orders" },
    { icon: <Import size={20} />, label: "Incoming Orders", path: "/warehouse/incomingorders" },

    { icon: <Truck size={20} />, label: "Delivery", path: "/admin/shippingqueue" },
    { icon: <ListChecks size={20} />, label: "Inventory Check", path: "/warehouse/inventorycheck" },
  ];

  // Unified logout function with fallback
  const handleLogout = () => {
    // Clear all possible token keys
    const tokenKeys = ['authToken', 'access_token', 'token', 'jwt'];
    tokenKeys.forEach(key => localStorage.removeItem(key));

    // Call parent logout if provided
    if (onLogout && typeof onLogout === 'function') {
      onLogout();
    }

    // Force full redirect to login (clears React state)
    window.location.href = '/admin/login';
  };

  return (
    <div className="w-64 bg-white border-r border-gray-200 h-screen fixed left-0 top-0 hidden lg:flex flex-col justify-between">
      <div>
        <div className="p-6">
          <div className="flex items-center gap-3">
            {/* Image Logo */}
            <img
              src="data:image/png;base64,"
              alt="Bookstore Logo"
              className="w-20 h-20"
            />
            <h1 className="text-xl font-semibold text-gray-900">
              Admin
            </h1>
          </div>
        </div>

        <nav className="px-3">
          {menuItems.map((item) => (
            <NavLink
              key={item.label}
              to={item.path}
              className={({ isActive }) =>
                `flex items-center gap-3 px-3 py-2.5 mb-1 rounded-lg transition-colors
                ${isActive
                  ? "bg-gray-100 text-gray-900 font-medium"
                  : "text-gray-600 hover:bg-gray-50"
                }`
              }
            >
              {item.icon}
              <span className="text-sm font-medium">{item.label}</span>
            </NavLink>
          ))}
        </nav>
      </div>

      {/* Logout Button */}
      <div className="p-4 border-t border-gray-200">
        <button
          onClick={handleLogout}
          className="flex items-center gap-3 px-3 py-2.5 w-full rounded-lg transition-colors text-red-600 hover:bg-red-50"
        >
          <LogOut size={20} />
          <span className="text-sm font-medium">Logout</span>
        </button>
      </div>
    </div>
  );
};

interface MobileDrawerProps {
  isOpen: boolean;
  onClose: () => void;
  onLogout?: () => void;
}

const MobileSidebarDrawer: React.FC<MobileDrawerProps> = ({
  isOpen,
  onClose,
  onLogout,
}) => {
  const menuItems: SidebarItem[] = [
    { icon: <Home size={20} />, label: "Dashboard", path: "/dashboard" },
    { icon: <Users size={20} />, label: "Users Management", path: "/admin/users" },
    { icon: <Book size={20} />, label: "Books Management", path: "/admin/books" },
    { icon: <BookPlus size={20} />, label: "Add Books", path: "/admin/addbookpage" },
    { icon: <ShoppingCart size={20} />, label: "Orders Management", path: "/admin/orders" },
    { icon: <Import size={20} />, label: "Incoming Orders", path: "/warehouse/incomingorders" },
    { icon: <Truck size={20} />, label: "Delivery", path: "/admin/shippingqueue" },
    { icon: <ListChecks size={20} />, label: "Inventory Check", path: "/warehouse/inventorycheck" },
  ];

  // Same unified logout for mobile
  const handleLogout = () => {
    const tokenKeys = ['authToken', 'access_token', 'token', 'jwt'];
    tokenKeys.forEach(key => localStorage.removeItem(key));

    if (onLogout && typeof onLogout === 'function') {
      onLogout();
    }

    onClose();
    window.location.href = '/admin/login';
  };

  if (!isOpen) return null;

  return (
    <>
      <div
        className="fixed inset-0 bg-black bg-opacity-50 z-40 lg:hidden"
        onClick={onClose}
      />
      <div className="fixed left-0 top-0 w-64 h-full bg-white z-50 lg:hidden flex flex-col justify-between overflow-y-auto">
        <div>
          <div className="p-6 flex items-center justify-between border-b border-gray-200">
            <div className="flex items-center gap-3">
            {/* Image Logo */}
            <img
              src="data:image/png;base64,"
              alt="Bookstore Logo"
              className="w-20 h-20"
            />
            <h1 className="text-xl font-semibold text-gray-900">
              Admin
            </h1>
          </div>
            <button
              onClick={onClose}
              className="p-2 hover:bg-gray-100 rounded-lg transition-colors"
            >
              <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <path d="M18 6L6 18" />
                <path d="M6 6l12 12" />
              </svg>
            </button>
          </div>

          <nav className="px-3 py-4">
            {menuItems.map((item) => (
              <NavLink
                key={item.label}
                to={item.path}
                onClick={onClose}
                className={({ isActive }) =>
                  `flex items-center gap-3 px-3 py-2.5 mb-1 rounded-lg transition-colors
                  ${isActive
                    ? "bg-gray-100 text-gray-900 font-medium"
                    : "text-gray-600 hover:bg-gray-50"
                  }`
                }
              >
                {item.icon}
                <span className="text-sm font-medium">{item.label}</span>
              </NavLink>
            ))}
          </nav>
        </div>

        {/* Mobile Logout Button */}
        <div className="p-4 border-t border-gray-200">
          <button
            onClick={handleLogout}
            className="flex items-center gap-3 px-3 py-2.5 w-full rounded-lg transition-colors text-red-600 hover:bg-red-50"
          >
            <LogOut size={20} />
            <span className="text-sm font-medium">Logout</span>
          </button>
        </div>
      </div>
    </>
  );
};

export { Sidebar, MobileSidebarDrawer };